package com.toxicorca.slideremote.demo

import android.net.Uri
import android.util.Log
import com.toxicorca.slideremote.SlideRemoteApp
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import java.io.File

/** Debug builds only: fake a connected PC and seed the sample deck for screenshots. */
object DemoSeeder {
    private const val TAG = "SlideRemoteDemo"
    private const val DECK_NAME = "Product Launch 2026"
    private const val ASSET = "demo/product-launch-2026.pdf"

    /** Slide titles for the sample PDF (generated by tools/make_demo_pdf.py). */
    private val TITLES = listOf(
        "Product Launch 2026", "Agenda", "The Problem", "Market Opportunity", "Product Overview", "Key Features",
        "Customer Research", "Pricing", "Launch Timeline", "Revenue Forecast", "Thank You", "Backup: Q&A",
    )
    private const val HIDDEN_SLIDE = 12
    private const val START_SLIDE = 4

    fun start(app: SlideRemoteApp) {
        app.hid.startDemo("Presentation PC")
        app.appScope.launch {
            app.decks.loaded.first { it }
            if (app.decks.decks.value.any { it.name == DECK_NAME }) return@launch
            val pdf = File(app.cacheDir, ASSET.substringAfterLast('/'))
            app.assets.open(ASSET).use { input -> pdf.outputStream().use { input.copyTo(it) } }
            try {
                // The same path a user's PDF import takes.
                val imported = app.importer.importPdf(Uri.fromFile(pdf)).deck
                app.decks.update(imported.id) { deck ->
                    deck.copy(
                        name = DECK_NAME,
                        columns = 3,
                        currentSlide = START_SLIDE,
                        slides = deck.slides.map { s ->
                            s.copy(
                                title = TITLES.getOrElse(s.number - 1) { "" },
                                hiddenInShow = s.number == HIDDEN_SLIDE,
                            )
                        },
                    )
                }
                Log.i(TAG, "Seeded demo deck")
            } catch (e: Exception) {
                Log.e(TAG, "Couldn't seed demo deck", e)
            } finally {
                pdf.delete()
            }
        }
    }
}
